-- ============================================================================
-- WezTerm configuration template for opencode
-- ============================================================================
-- Generated by _setup_terminal.ps1 or copy manually to:
--   Windows:  %USERPROFILE%\.config\wezterm\wezterm.lua
--   macOS:    ~/.config/wezterm/wezterm.lua
--   Linux:    ~/.config/wezterm/wezterm.lua
--
-- Reload: Ctrl+Shift+R (no restart needed)
-- ============================================================================

local wezterm = require("wezterm")
local config = wezterm.config_builder()

-- ---------------------------------------------------------------------------
-- Window
-- ---------------------------------------------------------------------------
config.initial_cols = 140
config.initial_rows = 40
config.window_decorations = "TITLE | RESIZE"
config.window_padding = { left = 8, right = 8, top = 8, bottom = 8 }
config.window_close_confirmation = "NeverPrompt"    -- no prompt on window close (X / Alt+F4)
config.window_background_opacity = 0.95
config.win32_system_backdrop = "Acrylic"

-- ---------------------------------------------------------------------------
-- Font — built-in JetBrains Mono with Nerd Font icons
-- ---------------------------------------------------------------------------
config.font = wezterm.font("JetBrains Mono")
config.font_size = 13.0

-- ---------------------------------------------------------------------------
-- Theme
-- ---------------------------------------------------------------------------
config.color_scheme = "Dracula"

-- ---------------------------------------------------------------------------
-- Graphics — Kitty protocol for opencode inline images (24-bit, animation)
-- opencode auto-detects WezTerm; falls back to symbols if off
-- ---------------------------------------------------------------------------
config.enable_kitty_graphics = true

-- ---------------------------------------------------------------------------
-- Shell (Windows default; override for your platform)
-- ---------------------------------------------------------------------------
-- config.default_prog = { "powershell.exe", "-NoLogo" }    -- Windows
-- config.default_prog = { "zsh", "-l" }                    -- macOS/Linux

-- ---------------------------------------------------------------------------
-- Launch menu — right-click the '+' tab button
-- ---------------------------------------------------------------------------
config.launch_menu = {
  { label = "PowerShell", args = { "powershell.exe", "-NoLogo" } },
  { label = "CMD",        args = { "cmd.exe" } },
}

-- ---------------------------------------------------------------------------
-- Leader key: Ctrl+A (tmux-style pane management)
-- ---------------------------------------------------------------------------
config.leader = { key = "a", mods = "CTRL", timeout_milliseconds = 1000 }

-- ---------------------------------------------------------------------------
-- Keys
-- ---------------------------------------------------------------------------
config.keys = {
  -- Copy/paste
  { key = "c", mods = "CTRL",       action = wezterm.action.CopyTo("Clipboard") },
  { key = "C", mods = "CTRL|SHIFT", action = wezterm.action.CopyTo("Clipboard") },
  { key = "v", mods = "CTRL",       action = wezterm.action.PasteFrom("Clipboard") },
  { key = "V", mods = "CTRL|SHIFT", action = wezterm.action.PasteFrom("Clipboard") },
  -- Tabs
  { key = "T", mods = "CTRL|SHIFT", action = wezterm.action.SpawnTab("CurrentPaneDomain") },
  { key = "w", mods = "CTRL",       action = wezterm.action.CloseCurrentTab({ confirm = false }) },
  -- Leader + | : vertical split
  { key = "|", mods = "LEADER", action = wezterm.action.SplitHorizontal({ domain = "CurrentPaneDomain" }) },
  -- Leader + - : horizontal split
  { key = "-", mods = "LEADER", action = wezterm.action.SplitVertical({ domain = "CurrentPaneDomain" }) },
  -- Leader + arrows : navigate panes
  { key = "LeftArrow",  mods = "LEADER", action = wezterm.action.ActivatePaneDirection("Left") },
  { key = "RightArrow", mods = "LEADER", action = wezterm.action.ActivatePaneDirection("Right") },
  { key = "UpArrow",    mods = "LEADER", action = wezterm.action.ActivatePaneDirection("Up") },
  { key = "DownArrow",  mods = "LEADER", action = wezterm.action.ActivatePaneDirection("Down") },
}

-- ---------------------------------------------------------------------------
-- Performance
-- ---------------------------------------------------------------------------
config.max_fps = 60
config.audible_bell = "Disabled"
config.use_fancy_tab_bar = false
config.hide_mouse_cursor_when_typing = false

return config
